# Let's fetch the details for each unique song_id using the show_song API, so we can map song_ids to their full titles and artists.
# We'll build a mapping from song_id to "title by artist" for easy matching.
song_id_to_full_title = {}
for song_id in unique_song_ids:
    song = apis.spotify.show_song(song_id=song_id)
    if "title" in song and "artists" in song and song["artists"]:
        artist_names = ", ".join(artist["name"] for artist in song["artists"])
        full_title = f"{song['title']} by {artist_names}"
        song_id_to_full_title[song_id] = full_title
print(song_id_to_full_title)

